/**
 * tree.js — Veliatychi family tree visualiser
 *
 * Data is loaded from JSON files in data/ (generated by export.py).
 * Navigation is driven by URL hash: #<person_id>
 */

'use strict';

// ── Configuration ────────────────────────────────────────────
const CONFIG = {
  homeId:   11083,      // default person on first load — change to suit
  dataDir:  'data/',
  dataFiles: ['si', 'parents', 'children', 'marriages', 'places', 'nums', 'births', 'deaths'],
};

// ── Layout constants ─────────────────────────────────────────
const NODE_W   = 152;  // node width (px)
const NODE_H   = 88;   // node min-height (px) — used for spacing only
const GAP_X    = 20;   // horizontal gap between sibling nodes
const GAP_Y    = 80;   // vertical gap between generation rows
const ROW_H    = NODE_H + GAP_Y;
const SP_GAP   = 32;   // gap between root node edge and spouse node edge
const FAM_GAP  = 40;   // gap between children groups of different spouses
const STAGGER  = 22;   // vertical stagger between family drop bars (px)
const LABEL_W  = 90;   // left margin reserved for generation labels

// Derived row Y positions (relative to canvas top)
const Y_GGP  = 24;                    // great-grandparents
const Y_GP   = Y_GGP + ROW_H;        // grandparents
const Y_PAR  = Y_GP  + ROW_H;        // parents + root + spouses
const HLINE_Y    = Y_PAR + Math.round(NODE_H / 2);  // marriage line Y

// ── Global data store ─────────────────────────────────────────
// Populated by loadData(). Short names match JSON file names.
let SI; // search index: [[id, sex, given, patronymic, surname, maiden, birth_year], ...]
let PA; // parents:      {child_id: [father_id, mother_id]}
let CH; // children:     {parent_id: [child_id, ...]}
let MA; // marriages:    {person_id: [[spouse_id, [y,m,d], [child_ids]], ...]}
let PL; // places:       {person_id: "place name"}
let NU; // nums:         {person_id: integer}
let BI; // births:       {person_id: [y, m, d]}
let DE; // deaths:       {person_id: [y, m, d]}

let currentRootId = null;
let currentMode = 'descendants';
let descendantGenerationLimit = null;
let currentComparison = null;
let contextComparisonPerson = null;

const TREE_MODES = new Set(['ancestors', 'descendants']);

function modeFromUrl() {
  const mode = new URLSearchParams(location.search || '').get('mode');
  return TREE_MODES.has(mode) ? mode : 'descendants';
}

function syncModeButtons() {
  document.querySelectorAll('.mode-btn').forEach(button => {
    button.classList.toggle('mode-btn-active', button.dataset.mode === currentMode);
  });
}

function syncTreeUrl(personId) {
  const params = new URLSearchParams(location.search || '');
  params.delete('compare');
  if (currentMode === 'descendants') params.delete('mode');
  else params.set('mode', currentMode);

  const search = params.toString();
  const path = location.pathname || '';
  const nextUrl = `${path}${search ? `?${search}` : ''}#${getUrlId(personId)}`;
  const currentUrl = `${path}${location.search || ''}${location.hash || ''}`;
  if (currentUrl !== nextUrl) history.replaceState(null, '', nextUrl);
}

function syncComparisonUrl(firstId, secondId) {
  const params = new URLSearchParams(location.search || '');
  params.delete('mode');
  params.delete('compare');

  const otherSearch = params.toString();
  const comparisonSearch = `compare=${getUrlId(firstId)},${getUrlId(secondId)}`;
  const search = [otherSearch, comparisonSearch].filter(Boolean).join('&');
  const path = location.pathname || '';
  const nextUrl = `${path}${search ? `?${search}` : ''}`;
  const currentUrl = `${path}${location.search || ''}${location.hash || ''}`;
  if (currentUrl !== nextUrl) history.replaceState(null, '', nextUrl);
}

function comparisonFromUrl() {
  const value = new URLSearchParams(location.search || '').get('compare');
  if (!value) return null;
  const identifiers = value.split(',').map(identifier => identifier.trim());
  if (identifiers.length !== 2 || identifiers.some(identifier => !identifier)) return null;
  const ids = identifiers.map(resolvePersonId);
  const canonical = ids.map(getUrlId);
  if (ids[0] === ids[1] || canonical.some((identifier, index) => identifier !== identifiers[index])) {
    return null;
  }
  return ids;
}

// ── Bootstrap ────────────────────────────────────────────────
(async function init() {
  await loadData();
  currentMode = modeFromUrl();
  const comparisonIds = comparisonFromUrl();
  if (comparisonIds) renderCommonAncestorTree(comparisonIds[0], comparisonIds[1]);
  else {
    const startId = resolvePersonId(location.hash.slice(1));
    renderTree(buildTree(startId));
  }
  initSearch();
  initUI();
})();

// ── Data loading ─────────────────────────────────────────────
async function loadData() {
  const fill = document.getElementById('loading-fill');
  const msg  = document.getElementById('loading-msg');
  msg.textContent = 'Загрузка дадзеных радавода...';

  try {
    const results = {};
    for (let i = 0; i < CONFIG.dataFiles.length; i++) {
      const name = CONFIG.dataFiles[i];
      const resp = await fetch(CONFIG.dataDir + name + '.json');
      if (!resp.ok) throw new Error(`Failed to fetch ${name}.json (HTTP ${resp.status})`);
      results[name] = await resp.json();
      fill.style.width = Math.round((i + 1) / CONFIG.dataFiles.length * 100) + '%';
    }
    ({ si: SI, parents: PA, children: CH, marriages: MA,
       places: PL, nums: NU, births: BI, deaths: DE } = results);
    document.getElementById('loading').style.display = 'none';

  } catch (err) {
    document.getElementById('loading').style.display = 'none';
    document.getElementById('err-msg').textContent =
      err.message + '\n\nПераканайцеся, што файлы JSON знаходзяцца ў папцы data/. Запусціце export.py для іх стварэння.';
    document.getElementById('err').style.display = 'flex';
    throw err; // stop execution
  }
}

// ── ID Mapping (database ID ↔ custom ID) ──────────────────────

/** Resolve a URL identifier to a database ID */
function resolvePersonId(identifier) {
  if (!identifier) return CONFIG.homeId;
  
  // Check if it's a database ID (prefixed with ~)
  if (identifier.startsWith('~')) {
    const dbId = parseInt(identifier.slice(1), 10);
    if (!isNaN(dbId) && dbId > 0) {
      if (SI.some(x => x[0] === dbId) || BI[dbId] || DE[dbId]) {
        return dbId;
      }
    }
    return CONFIG.homeId;
  }
  
  // Otherwise try custom ID first
  const id = parseInt(identifier, 10);
  if (isNaN(id) || id <= 0) return CONFIG.homeId;
  
  // Try to find by custom ID (num field) first
  for (const [dbId, customId] of Object.entries(NU)) {
    if (customId === id) {
      return parseInt(dbId, 10);
    }
  }

  // Fall back to database ID if custom ID not found
  if (SI.some(x => x[0] === id) || BI[id] || DE[id]) {
    return id;
  }

  // Not found - use default
  return CONFIG.homeId;
}

/** Get the display ID for a person (custom ID if available, otherwise database ID) */
function getDisplayId(dbId) {
  return NU[dbId] ?? dbId;
}

/** Get the URL-safe identifier for a person (custom ID or ~dbId) */
function getUrlId(dbId) {
  const customId = NU[dbId];
  if (customId != null) {
    return String(customId);
  }
  return `~${dbId}`;
}

function getDocumentsUrl(person) {
  if (person.num == null) return null;
  return `https://wielatycze.github.io/agg/?id=${encodeURIComponent(person.num)}`;
}

// ── Data helpers ─────────────────────────────────────────────

/** Format a [year, month, day] date tuple as dd.mm.yyyy */
function formatDate(d) {
  if (!d) return '?';
  const [y, m, dd] = d;
  if (!y)  return '?';
  if (!m)  return String(y);
  const pad = n => n ? String(n).padStart(2, '0') : '??';
  if (!dd) return `??.${pad(m)}.${y}`;
  return `${pad(dd)}.${pad(m)}.${y}`;
}

/** Build a display name: Surname (Maiden) Given Patronymic */
function formatName(given, patronymic, surname, maiden) {
  const surnamePart = surname
    ? (maiden && maiden !== surname ? `${surname} (${maiden})` : surname)
    : (maiden || null);
  return [surnamePart, given, patronymic].filter(Boolean).join(' ');
}

/** Build a person object from the data store */
/** Build a person object from the data store */
function buildPerson(id) {
  if (!id) return null;
  const r = SI.find(x => x[0] == id);
  if (!r && !BI[id] && !DE[id]) return null;
  return {
    id,
    sex:        r ? r[1] : 0,
    given:      r ? r[2] : null,
    patronymic: r ? r[3] : null,
    surname:    r ? r[4] : null,
    maiden:     r ? r[5] : null,
    birth:      BI[id] || null,
    death:      DE[id] || null,
    place:      PL[id] || null,
    num:        NU[id] ?? null,
  };
}

/**
 * Recursively build an ancestor subtree node.
 * Each node: { person, father, mother } (father/mother are ancestor nodes or null).
 */
function buildAncestorNode(id, seen = new Set()) {
  if (!id) return null;
  const key = String(id);
  if (seen.has(key)) return null;
  const person = buildPerson(id);
  if (!person) return null;
  const nextSeen = new Set(seen);
  nextSeen.add(key);
  const [fatherId, motherId] = PA[id] || [null, null];
  return {
    person,
    father: buildAncestorNode(fatherId, nextSeen),
    mother: buildAncestorNode(motherId, nextSeen),
  };
}

/** Compute subtree extents from a person's centre. */
function ancestorExtents(node) {
  if (!node) return { left: 0, right: 0 };
  const self = NODE_W / 2;
  const fatherExt = ancestorExtents(node.father);
  const motherExt = ancestorExtents(node.mother);

  if (node.father && node.mother) {
    const parentOffset = (fatherExt.right + GAP_X + motherExt.left) / 2;
    return {
      left: Math.max(self, parentOffset + fatherExt.left),
      right: Math.max(self, parentOffset + motherExt.right),
    };
  }

  if (node.father) {
    return {
      left: Math.max(self, fatherExt.left),
      right: Math.max(self, fatherExt.right),
    };
  }

  if (node.mother) {
    return {
      left: Math.max(self, motherExt.left),
      right: Math.max(self, motherExt.right),
    };
  }

  return { left: self, right: self };
}

/**
 * Assign cx (horizontal centre) to every ancestor node, top-down.
 * Returns flat array of { person, cx, depth } for all ancestors.
 * depth=0 is the root, depth=1 is parents, etc.
 */
function assignAncestorPositions(node, cx, depth, results = []) {
  if (!node) return results;
  results.push({ node, person: node.person, cx, depth });
  if (node.father && node.mother) {
    const fatherExt = ancestorExtents(node.father);
    const motherExt = ancestorExtents(node.mother);
    const parentOffset = (fatherExt.right + GAP_X + motherExt.left) / 2;
    assignAncestorPositions(node.father, cx - parentOffset, depth + 1, results);
    assignAncestorPositions(node.mother, cx + parentOffset, depth + 1, results);
  } else if (node.father) {
    assignAncestorPositions(node.father, cx, depth + 1, results);
  } else if (node.mother) {
    assignAncestorPositions(node.mother, cx, depth + 1, results);
  }
  return results;
}

function buildAncestorGraphLayout(ancestorTree, rootCx) {
  const occurrences = assignAncestorPositions(ancestorTree, rootCx, 0);
  const nodesById = new Map();
  const edgeKeys = new Set();
  const edges = [];

  occurrences.forEach(pos => {
    const id = String(pos.person.id);
    const existing = nodesById.get(id);
    if (!existing) {
      nodesById.set(id, {
        person: pos.person,
        depth: pos.depth,
        occurrencePositions: [pos],
      });
    } else {
      existing.depth = Math.max(existing.depth, pos.depth);
      existing.occurrencePositions.push(pos);
    }
  });

  occurrences.forEach(pos => {
    [
      ['father', pos.node.father],
      ['mother', pos.node.mother],
    ].forEach(([kind, parentNode]) => {
      if (!parentNode) return;
      const key = `${parentNode.person.id}:${pos.person.id}:${kind}`;
      if (edgeKeys.has(key)) return;
      edgeKeys.add(key);
      edges.push({
        kind,
        parentId: String(parentNode.person.id),
        childId: String(pos.person.id),
      });
    });
  });

  const nodes = Array.from(nodesById.entries()).map(([id, node]) => {
    const deepest = node.occurrencePositions.filter(pos => pos.depth === node.depth);
    const cx = deepest.reduce((sum, pos) => sum + pos.cx, 0) / deepest.length;
    return { id, person: node.person, depth: node.depth, cx };
  });

  const rows = new Map();
  nodes.forEach(node => {
    if (!rows.has(node.depth)) rows.set(node.depth, []);
    rows.get(node.depth).push(node);
  });

  rows.forEach(row => {
    row.sort((a, b) => a.cx - b.cx || Number(a.id) - Number(b.id));
    for (let i = 1; i < row.length; i += 1) {
      const minCx = row[i - 1].cx + NODE_W + GAP_X;
      if (row[i].cx < minCx) row[i].cx = minCx;
    }
  });

  return { nodes, edges };
}

/** Build the full tree data structure centred on rootId. */
function buildTree(rootId) {
  const root = buildPerson(rootId);
  if (!root) return null;

  const [fatherId, motherId] = PA[rootId] || [null, null];
  const ancestorTree = {
    person: root,
    father: buildAncestorNode(fatherId, new Set([String(rootId)])),
    mother: buildAncestorNode(motherId, new Set([String(rootId)])),
  };

  const families = (MA[rootId] || []).map(([spouseId, marriageDate, childIds]) => {
    // childIds from MA is the per-couple list; fall back to all children if empty
    const children = (childIds && childIds.length)
      ? childIds.map(buildPerson).filter(Boolean)
      : [];
    return {
      spouse:   buildPerson(spouseId),
      date:     marriageDate,
      children,
    };
  });

  // Fallback: no marriage records at all — use CH map
  if (!families.length) {
    const ch = (CH[rootId] || []).map(buildPerson).filter(Boolean);
    if (ch.length) families.push({ spouse: null, date: null, children: ch });
  }

  // Any children not accounted for in MA get their own anonymous family
  const allKnownChildren = new Set(families.flatMap(f => f.children.map(c => c.id)));
  const chChildren = (CH[rootId] || []).map(buildPerson).filter(Boolean);
  const unknownChildren = chChildren.filter(c => !allKnownChildren.has(c.id));
  if (unknownChildren.length) {
    families.push({ spouse: null, date: null, children: unknownChildren });
  }

  // Remove families that have neither spouse nor children (nothing to show)
  const validFamilies = families.filter(f => f.spouse || f.children.length);

  validFamilies.forEach(fam => {
    fam.children.sort((a, b) =>
      ((a.birth && a.birth[0]) || 9999) - ((b.birth && b.birth[0]) || 9999)
    );
  });

  return { ancestorTree, families: validFamilies };
}

function birthYear(person) {
  if (!person) return 9999;
  if (person.birth && person.birth[0]) return person.birth[0];
  const r = SI.find(x => x[0] == person.id);
  return (r && r[6]) || 9999;
}

function buildFamilyGroups(personId) {
  const families = (MA[personId] || []).map(([spouseId, marriageDate, childIds]) => {
    const children = (childIds && childIds.length)
      ? childIds.map(buildPerson).filter(Boolean)
      : [];
    return {
      spouse: buildPerson(spouseId),
      date: marriageDate,
      children,
    };
  });

  if (!families.length) {
    const ch = (CH[personId] || []).map(buildPerson).filter(Boolean);
    if (ch.length) families.push({ spouse: null, date: null, children: ch });
  }

  const allKnownChildren = new Set(families.flatMap(f => f.children.map(c => c.id)));
  const chChildren = (CH[personId] || []).map(buildPerson).filter(Boolean);
  const unknownChildren = chChildren.filter(c => !allKnownChildren.has(c.id));
  if (unknownChildren.length) {
    families.push({ spouse: null, date: null, children: unknownChildren });
  }

  const validFamilies = families.filter(f => f.spouse || f.children.length);
  validFamilies.forEach(fam => {
    fam.children.sort((a, b) => birthYear(a) - birthYear(b));
  });

  return validFamilies;
}

const descendantLayout = DescendantLayout.create({
  nodeWidth: NODE_W,
  gapX: GAP_X,
  spouseGap: SP_GAP,
  familyGap: FAM_GAP,
  stagger: STAGGER,
  birthYear,
  getFamilies: buildFamilyGroups,
  treeLayout: TreeLayout,
});

function resolveDescendantGenerationLimit() {
  return descendantGenerationLimit == null ? Infinity : Math.max(1, descendantGenerationLimit);
}

function computeDescendantDepth(personId, maxDepth = Infinity) {
  return descendantLayout.computeDepth(personId, maxDepth);
}

function computeDescendantLayout(personId, remainingGenerations = Infinity) {
  return descendantLayout.computeLayout(personId, remainingGenerations);
}

function computeDescendantWidth(personId) {
  return computeDescendantLayout(personId, resolveDescendantGenerationLimit()).width;
}

// ── Layout helpers ───────────────────────────────────────────

/** X centre of a node placed at left edge x */
const nodeCx = x => x + NODE_W / 2;

/** Y bottom of a node placed at top edge y */
const nodeBot = y => y + NODE_H;

// ── SVG helpers ──────────────────────────────────────────────

function svgEl(tag, attrs) {
  const el = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
  return el;
}

function drawLine(svg, x1, y1, x2, y2, stroke, dashed = false, strokeWidth = 1.5) {
  const attrs = { x1, y1, x2, y2, stroke, 'stroke-width': strokeWidth, 'data-segment': '1' };
  if (dashed) attrs['stroke-dasharray'] = '5,4';
  const line = svgEl('line', attrs);
  svg.appendChild(line);
  // Track line for crossing detection
  if (!svg.lineSegments) svg.lineSegments = [];
  svg.lineSegments.push({ line, x1, y1, x2, y2, stroke, strokeWidth, dashed });
}

// Detect if two line segments intersect
function segmentsIntersect(p1, p2, p3, p4) {
  const ccw = (A, B, C) => (C.y - A.y) * (B.x - A.x) > (B.y - A.y) * (C.x - A.x);
  return ccw(p1, p3, p4) !== ccw(p2, p3, p4) && ccw(p1, p2, p3) !== ccw(p1, p2, p4);
}

// Find intersection point of two line segments (only if both segments actually cross)
function lineIntersection(x1, y1, x2, y2, x3, y3, x4, y4) {
  const denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(denom) < 0.001) return null; // Parallel or collinear
  
  const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
  const u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;
  
  // Both t and u must be within [0, 1] for segments to actually intersect
  if (t < 0.01 || t > 0.99 || u < 0.01 || u > 0.99) return null;
  
  return {
    x: x1 + t * (x2 - x1),
    y: y1 + t * (y2 - y1)
  };
}

// Draw bridge for a line that crosses another - gap in the middle
function drawLineWithBridge(svg, x1, y1, x2, y2, stroke, crossings = [], strokeWidth = 1.5) {
  if (!crossings.length) {
    drawLine(svg, x1, y1, x2, y2, stroke, false, strokeWidth);
    return;
  }
  
  const isVertical = Math.abs(x2 - x1) < 0.1;
  const isHorizontal = Math.abs(y2 - y1) < 0.1;
  
  // Sort crossings by distance along the line
  crossings.sort((a, b) => {
    if (isVertical) return a.y - b.y;
    if (isHorizontal) return a.x - b.x;
    const distA = Math.hypot(a.x - x1, a.y - y1);
    const distB = Math.hypot(b.x - x1, b.y - y1);
    return distA - distB;
  });
  
  const totalDist = Math.hypot(x2 - x1, y2 - y1);
  const gap = Math.min(8, totalDist * 0.1); // Proportional gap size
  let lastEnd = { x: x1, y: y1 };
  
  for (const cross of crossings) {
    const dx = cross.x - x1;
    const dy = cross.y - y1;
    const dist = Math.hypot(dx, dy);
    
    // Skip if crossing too close to start/end
    if (dist < gap * 1.5 || dist > totalDist - gap * 1.5) continue;
    
    const ratio = dist / totalDist;
    const gapRatio = gap / totalDist;
    
    const gapStartX = x1 + (x2 - x1) * Math.max(0, ratio - gapRatio);
    const gapStartY = y1 + (y2 - y1) * Math.max(0, ratio - gapRatio);
    
    // Draw line from last point to gap start
    drawLine(svg, lastEnd.x, lastEnd.y, gapStartX, gapStartY, stroke, false, strokeWidth);
    
    lastEnd = {
      x: x1 + (x2 - x1) * Math.min(1, ratio + gapRatio),
      y: y1 + (y2 - y1) * Math.min(1, ratio + gapRatio)
    };
  }
  
  // Draw final segment
  drawLine(svg, lastEnd.x, lastEnd.y, x2, y2, stroke, false, strokeWidth);
}

// Apply bridge effects to lines that cross over others
function applyBridges(svg) {
  if (!svg.lineSegments || svg.lineSegments.length < 2) return;
  
  const segments = svg.lineSegments;
  const crossingsBySegment = new Map();
  
  // Find all crossings
  for (let i = 0; i < segments.length; i++) {
    for (let j = i + 1; j < segments.length; j++) {
      const s1 = segments[i];
      const s2 = segments[j];
      const intersection = lineIntersection(s1.x1, s1.y1, s1.x2, s1.y2, s2.x1, s2.y1, s2.x2, s2.y2);
      
      if (intersection) {
        // s1 is drawn first (under), s2 crosses over it
        if (!crossingsBySegment.has(j)) crossingsBySegment.set(j, []);
        crossingsBySegment.get(j).push(intersection);
      }
    }
  }
  
  if (crossingsBySegment.size === 0) return;
  
  // Redraw lines that have crossings with bridges
  crossingsBySegment.forEach((crossings, idx) => {
    const seg = segments[idx];
    seg.line.remove();
    drawLineWithBridge(svg, seg.x1, seg.y1, seg.x2, seg.y2, seg.stroke, 
                      crossings, seg.strokeWidth);
  });
}

// Draw a horizontal bar
function drawBar(svg, cx1, cx2, y, stroke) {
  drawLine(svg, Math.min(cx1, cx2), y, Math.max(cx1, cx2), y, stroke);
}

// ── Node DOM helpers ─────────────────────────────────────────

function createNode(person, x, y, isRoot = false) {
  if (!person) return null;
  const name = formatName(person.given, person.patronymic, person.surname, person.maiden)
             || `Асоба #${person.id}`;
  const dates = (person.birth || person.death)
    ? `${formatDate(person.birth)} — ${formatDate(person.death)}` : '';
  const div = document.createElement('div');
  div.className = ['node',
    person.sex === 1 ? 'sex-m' : person.sex === 2 ? 'sex-f' : '',
    isRoot ? 'is-root' : ''].filter(Boolean).join(' ');
  div.style.cssText = `left:${x}px;top:${y}px`;
  div.dataset.id = person.id;
  div.innerHTML = [
    `<div class="node-name">${name}</div>`,
    dates        ? `<div class="node-dates">${dates}</div>` : '',
    person.place ? `<div class="node-place">${person.place}</div>` : '',
    person.num != null
      ? `<a class="node-num" href="${getDocumentsUrl(person)}" aria-label="Дакументы: #${person.num}" title="Дакументы">#${person.num}</a>`
      : '',
  ].join('');
  div.addEventListener('click', event => {
    if (event.target.closest && event.target.closest('.node-num')) return;
    showDetailPanel(person, div);
  });
  div.addEventListener('contextmenu', event => {
    if (event.target.closest && event.target.closest('.node-num')) return;
    event.preventDefault();
    showPersonContextMenu(person, event.clientX, event.clientY);
  });
  return div;
}

// ── Render ───────────────────────────────────────────────────

function renderTree(tree) {
  if (!tree) return;

  const canvas = document.getElementById('canvas');
  canvas.innerHTML = '';

  const { ancestorTree, families } = tree;
  const visualFamilies = currentMode === 'descendants'
    ? descendantLayout.orderFamilies(families)
    : families;

  // ── Ancestor depth & Y_ROOT ───────────────────────────────
  const actualDepth = (function maxDepth(node) {
    if (!node) return 0;
    return 1 + Math.max(maxDepth(node.father), maxDepth(node.mother));
  })(ancestorTree) - 1;

  const Y_ROOT      = 24 + actualDepth * ROW_H;
  const HLINE_Y     = Y_ROOT + Math.round(NODE_H / 2);

  // ── Spouse layout offsets ─────────────────────────────────
  const MARGIN  = 20;
  const {
    orderedFams,
    leftSpouseOffsets,
    rightSpouseOffsets,
    spouseOffsets,
    marriageFromOffsets,
  } = descendantLayout.splitFamilies(visualFamilies);

  // ── Compute below-root width ───────────────────────────────
  const descendantLimit = resolveDescendantGenerationLimit();
  const belowLayout = currentMode === 'descendants'
    ? computeDescendantLayout(ancestorTree.person.id, descendantLimit)
    : null;
  const belowLeftNeeded = belowLayout ? belowLayout.rootOffset : 0;
  const belowRightNeeded = belowLayout ? belowLayout.width - belowLayout.rootOffset : 0;

  // ── Resolve rootCx ────────────────────────────────────────
  const visibleLeftSpouseOffsets = leftSpouseOffsets.filter(Number.isFinite);
  const leftSpouseNeeded = visibleLeftSpouseOffsets.length
    ? -(visibleLeftSpouseOffsets[visibleLeftSpouseOffsets.length-1] - NODE_W/2) : 0;
  const ancestorBounds = ancestorExtents(ancestorTree);

  const rootCxRaw = Math.max(
    MARGIN + leftSpouseNeeded,
    MARGIN + belowLeftNeeded,
    MARGIN + ancestorBounds.left,
  );

  const ancestorPositions = assignAncestorPositions(ancestorTree, rootCxRaw, 0);
  const minAncCx = ancestorPositions.reduce((m, p) => Math.min(m, p.cx), rootCxRaw);
  const shift    = Math.max(0, MARGIN + NODE_W/2 - minAncCx);
  const rootCx   = rootCxRaw + shift;

  // Always use ancestor graph layout for consistent rendering in both modes
  const ancestorGraph = buildAncestorGraphLayout(ancestorTree, rootCx);
  const positions = ancestorGraph.nodes;
  const posByNode = null;
  const posById = new Map(positions.map(p => [p.id, p]));

  // ── Canvas size ───────────────────────────────────────────
  const visibleRightSpouseOffsets = rightSpouseOffsets.filter(Number.isFinite);
  const rightSpouseNeeded = visibleRightSpouseOffsets.length
    ? visibleRightSpouseOffsets[visibleRightSpouseOffsets.length-1] + NODE_W/2 : NODE_W/2;
  const maxAncCx = positions.reduce((m, p) => Math.max(m, p.cx), rootCx);

  const canvasW = Math.ceil(Math.max(
    maxAncCx + NODE_W/2 + MARGIN,
    rootCx + rightSpouseNeeded + MARGIN,
    rootCx + belowRightNeeded + MARGIN,
  ));
  const descendantDepth = currentMode === 'descendants'
    ? computeDescendantDepth(ancestorTree.person.id, descendantLimit)
    : 0;
  const canvasH = Y_ROOT
    + (descendantDepth + 1) * ROW_H
    + 40;

  canvas.style.cssText = `width:${canvasW}px;height:${canvasH}px;position:relative`;
  const svg = svgEl('svg', { class: 'connectors', style: `width:${canvasW}px;height:${canvasH}px` });
  canvas.appendChild(svg);

  const nodeElementsById = new Map();

  function placeNode(person, cx, y, isRoot = false) {
    const node = createNode(person, cx - NODE_W/2, y, isRoot);
    if (node) {
      canvas.appendChild(node);
      nodeElementsById.set(String(person.id), node);
    }
  }

  function renderedNodeBottom(personId, y) {
    const node = nodeElementsById.get(String(personId));
    return y + Math.max(NODE_H, node ? node.offsetHeight : 0);
  }

  // ── Place ancestor nodes ──────────────────────────────────
  positions.forEach(({ person, cx, depth }) => {
    placeNode(person, cx, Y_ROOT - depth * ROW_H, depth === 0);
  });

  // ── Ancestor connectors ───────────────────────────────────
  const edgesByChild = new Map();
  ancestorGraph.edges.forEach(edge => {
    if (!edgesByChild.has(edge.childId)) edgesByChild.set(edge.childId, []);
    edgesByChild.get(edge.childId).push(edge);
  });

  edgesByChild.forEach((edges, childId) => {
    const childPos = posById.get(childId);
    if (!childPos) return;
    const childY = Y_ROOT - childPos.depth * ROW_H;
    const fatherEdge = edges.find(edge => edge.kind === 'father');
    const motherEdge = edges.find(edge => edge.kind === 'mother');
    const fpos = fatherEdge ? posById.get(fatherEdge.parentId) : null;
    const mpos = motherEdge ? posById.get(motherEdge.parentId) : null;

    if (fpos && mpos) {
      const fatherY = Y_ROOT - fpos.depth * ROW_H;
      const motherY = Y_ROOT - mpos.depth * ROW_H;
      const fatherBottom = renderedNodeBottom(fpos.id, fatherY);
      const motherBottom = renderedNodeBottom(mpos.id, motherY);
      const coupleY = Math.min(
        childY - 8,
        Math.max(fatherBottom, motherBottom) + Math.round(GAP_Y * 0.5)
      );
      const barMid = (fpos.cx + mpos.cx) / 2;

      drawLine(svg, fpos.cx, fatherBottom, fpos.cx, coupleY, '#999');
      drawLine(svg, mpos.cx, motherBottom, mpos.cx, coupleY, '#999');
      drawLine(svg, fpos.cx, coupleY, mpos.cx, coupleY, '#aaa');
      if (Math.abs(barMid - childPos.cx) > 0.5) {
        const branchY = Math.min(childY - 8, coupleY + 16);
        drawLine(svg, barMid, coupleY, barMid, branchY, '#999');
        drawLine(svg, barMid, branchY, childPos.cx, branchY, '#999');
        drawLine(svg, childPos.cx, branchY, childPos.cx, childY, '#999');
      } else {
        drawLine(svg, childPos.cx, coupleY, childPos.cx, childY, '#999');
      }
    } else {
      const parentPos = fpos || mpos;
      if (!parentPos) return;
      const parentY = Y_ROOT - parentPos.depth * ROW_H;
      const parentBottom = renderedNodeBottom(parentPos.id, parentY);
      const color = fpos ? '#999' : '#999';
      const elbowY = Math.min(childY - 8, parentBottom + Math.round(GAP_Y * 0.5));

      drawLine(svg, parentPos.cx, parentBottom, parentPos.cx, elbowY, color);
      if (Math.abs(parentPos.cx - childPos.cx) > 0.5) {
        drawLine(svg, parentPos.cx, elbowY, childPos.cx, elbowY, color);
      }
      drawLine(svg, childPos.cx, elbowY, childPos.cx, childY, color);
    }
  });

  // ── Spouses + marriage hlines ─────────────────────────────
  if (currentMode !== 'descendants') {
    orderedFams.forEach((fam, i) => {
      if (!fam.spouse) return;
      const spouseCx = rootCx + spouseOffsets[i];
      const marriageFromCx = rootCx + marriageFromOffsets[i];
      placeNode(fam.spouse, spouseCx, Y_ROOT);
      drawLine(svg, marriageFromCx, HLINE_Y, spouseCx, HLINE_Y, '#999', true);
    });
  }

  // ── Below root: draw descendants ───────────────────────────
  if (currentMode === 'descendants') {
    renderDescendants(svg, ancestorTree, rootCx, Y_ROOT, orderedFams, MARGIN, descendantLimit);
  }

function renderDescendants(svg, ancestorTree, rootCx, Y_ROOT, orderedFams, MARGIN, maxGenerations) {
  if (maxGenerations <= 0) return;
  const rootFamilies = orderedFams.filter(Boolean);
  let depth = 1;
  let queue = renderDescendantParent(svg, ancestorTree.person, rootCx, Y_ROOT, rootFamilies, true, MARGIN, maxGenerations);

  while (queue.length && depth < maxGenerations) {
    depth += 1;
    const nextQueue = [];
    for (const { person, cx, y } of queue) {
      const families = buildFamilyGroups(person.id).filter(Boolean);
      if (!families.length) continue;
      const remainingGenerations = maxGenerations - depth + 1;
      nextQueue.push(...renderDescendantParent(svg, person, cx, y, families, true, MARGIN, remainingGenerations));
    }
    queue = nextQueue;
  }
}

function renderDescendantParent(svg, parent, parentCx, parentY, families, renderSpouses, MARGIN, remainingGenerations) {
  if (!(families || []).length || remainingGenerations <= 0) return [];

  const Y_CH = parentY + ROW_H;
  const baseDropY = parentY + ROW_H - 16;
  const familyLayout = descendantLayout.positionChildFamilyBlocks(parentCx, families, remainingGenerations, MARGIN);
  const { positionedBlocks } = familyLayout;

  if (renderSpouses) {
    positionedBlocks.forEach(blk => {
      if (!blk.fam.spouse) return;
      placeNode(blk.fam.spouse, blk.spouseCx, parentY);
      const hlineY = parentY + Math.round(NODE_H / 2);
      drawLine(
        svg,
        blk.marriageFromCx,
        hlineY,
        blk.spouseCx,
        hlineY,
        positionedBlocks.length === 1 ? '#999' : '#aaa',
        true
      );
    });
  }

  const drawnAnchors = new Set();
  const childPositions = [];
  positionedBlocks.forEach(blk => {
    blk.stubStartY = blk.fam.spouse ? parentY + Math.round(NODE_H / 2) : nodeBot(parentY);
  });

  const familyRowBottom = positionedBlocks.reduce((bottom, blk) => {
    if (!blk.fam.spouse) return bottom;
    return Math.max(bottom, renderedNodeBottom(blk.fam.spouse.id, parentY));
  }, renderedNodeBottom(parent.id, parentY));
  const minimumDropY = familyRowBottom + 8;
  const effectiveLaneGap = descendantLayout.connectorLaneGap(
    positionedBlocks,
    baseDropY,
    minimumDropY
  );

  positionedBlocks.forEach((blk) => {
    const familyDropY = Math.max(
      minimumDropY,
      blk.stubStartY + 8,
      baseDropY - blk.connectorLane * effectiveLaneGap
    );
    const key = `${blk.anchorCx},${blk.stubStartY},${familyDropY}`;

    if (!drawnAnchors.has(key)) {
      drawnAnchors.add(key);
      drawLine(svg, blk.anchorCx, blk.stubStartY, blk.anchorCx, familyDropY, '#999');
    }

    if (blk.children.length > 1) drawBar(svg, blk.firstCx, blk.lastCx, familyDropY, '#999');
    if (blk.anchorCx < blk.firstCx) drawLine(svg, blk.anchorCx, familyDropY, blk.firstCx, familyDropY, '#999');
    else if (blk.anchorCx > blk.lastCx) drawLine(svg, blk.lastCx, familyDropY, blk.anchorCx, familyDropY, '#999');

    blk.children.forEach((child, ci) => {
      const childCx = blk.childBlockLeft + blk.childRootOffsets[ci];
      placeNode(child, childCx, Y_CH);
      drawLine(svg, childCx, familyDropY, childCx, Y_CH, '#999');
      childPositions.push({ person: child, cx: childCx, y: Y_CH });
    });
  });

  return childPositions;
}

  // ── Update state ──────────────────────────────────────────
  currentRootId = ancestorTree.person.id;
  const rootName = formatName(ancestorTree.person.given, ancestorTree.person.patronymic,
                              ancestorTree.person.surname, ancestorTree.person.maiden);
  const crumb = document.getElementById('crumb');
  crumb.textContent = rootName;
  crumb.title = rootName;
  document.getElementById('tree-count').textContent = `Асоб: ${nodeElementsById.size}`;
  const treeDocuments = document.getElementById('tree-documents');
  const treeDocumentsUrl = getDocumentsUrl(ancestorTree.person);
  treeDocuments.style.display = treeDocumentsUrl ? '' : 'none';
  if (treeDocumentsUrl) treeDocuments.href = treeDocumentsUrl;
  else treeDocuments.removeAttribute('href');
  updateDescendantLimitControl(currentRootId);

  syncTreeUrl(currentRootId);

  // Apply bridge effects to crossing lines
  applyBridges(svg);

  // Centre root in viewport
  {
    const wrap = document.getElementById('canvas-wrap');
    const toolbar = document.getElementById('toolbar');
    const vw = wrap.clientWidth || window.innerWidth;
    const vh = wrap.clientHeight || window.innerHeight - (toolbar ? toolbar.offsetHeight : 48);
    const targetX = Math.round(vw / 2);
    const targetY = Math.round(vh / 3);
    const padLeft = Math.max(0, targetX - rootCx);
    const treeNeedsScrolling = canvasW > vw || canvasH > vh;
    const topAlignDescendants = currentMode === 'descendants' &&
      actualDepth === 0 &&
      treeNeedsScrolling;
    const padTop = topAlignDescendants ? 0 : Math.max(0, targetY - Y_ROOT);
    canvas.style.cssText += `;margin-left:${padLeft}px;margin-top:${padTop}px`;
    wrap.scrollLeft = Math.max(0, rootCx + padLeft - targetX);
    wrap.scrollTop  = Math.max(0, Y_ROOT + padTop  - targetY);
  }
}

// ── Detail panel ─────────────────────────────────────────────

function showDetailPanel(person, node) {
  document.querySelectorAll('.node.is-selected').forEach(n => n.classList.remove('is-selected'));
  if (node) node.classList.add('is-selected');

  const name = formatName(person.given, person.patronymic, person.surname, person.maiden)
             || `Асоба #${person.id}`;
  document.getElementById('detail-name').textContent = name;

  const infoParts = [];
  if (person.birth) infoParts.push(`Нар.: ${formatDate(person.birth)}`);
  if (person.death) infoParts.push(`Пам.: ${formatDate(person.death)}`);
  if (person.place) infoParts.push(person.place);
  if (person.num != null) infoParts.push(`#${person.num}`);
  document.getElementById('detail-info').textContent = infoParts.join('  ·  ');

  const nav = document.getElementById('detail-nav');
  nav.innerHTML = '';
  if (currentComparison || person.id !== currentRootId) {
    const btn = document.createElement('button');
    btn.className = 'nav-btn';
    btn.textContent = 'Паказаць дрэва →';
    btn.addEventListener('click', () => navigate(person.id));
    nav.appendChild(btn);
  }

  const documentsUrl = getDocumentsUrl(person);
  if (documentsUrl) {
    const documentsLink = document.createElement('a');
    documentsLink.className = 'nav-btn documents-link';
    documentsLink.textContent = 'Дакументы →';
    documentsLink.href = documentsUrl;
    nav.appendChild(documentsLink);
  }

  document.getElementById('detail-panel').style.display = 'flex';
}

// ── Navigation ───────────────────────────────────────────────

function hidePersonContextMenu() {
  const menu = document.getElementById('person-context-menu');
  if (menu) menu.style.display = 'none';
}

function comparisonPersonName(person) {
  return formatName(person.given, person.patronymic, person.surname, person.maiden) ||
    `Асоба #${person.id}`;
}

function updateContextComparisonUi() {
  const status = document.getElementById('comparison-pick-status');
  const name = document.getElementById('comparison-pick-name');
  if (!status || !name) return;
  status.style.display = contextComparisonPerson ? 'flex' : 'none';
  name.textContent = contextComparisonPerson
    ? `Агульныя продкі: ${comparisonPersonName(contextComparisonPerson)}`
    : '';
}

function clearContextComparisonPerson() {
  contextComparisonPerson = null;
  updateContextComparisonUi();
}

function showPersonContextMenu(person, clientX, clientY) {
  const menu = document.getElementById('person-context-menu');
  const showTree = document.getElementById('context-show-tree');
  const compareLabel = document.getElementById('context-compare-label');
  const compareFrom = document.getElementById('context-compare-from');
  menu.dataset.personId = String(person.id);
  showTree.style.display = !currentComparison && person.id === currentRootId ? 'none' : 'flex';
  menu.classList.toggle('single-action', showTree.style.display === 'none');

  if (!contextComparisonPerson) {
    compareLabel.textContent = 'Выбраць для параўнання';
    compareFrom.style.display = 'none';
  } else if (contextComparisonPerson.id === person.id) {
    compareLabel.textContent = 'Скасаваць выбар';
    compareFrom.style.display = 'none';
  } else {
    compareLabel.textContent = 'Паказаць агульных продкаў';
    compareFrom.textContent = `з ${comparisonPersonName(contextComparisonPerson)}`;
    compareFrom.style.display = 'block';
  }
  menu.style.display = 'block';

  const menuWidth = menu.offsetWidth || 238;
  const menuHeight = menu.offsetHeight || (showTree.style.display === 'none' ? 44 : 84);
  const left = Math.max(8, Math.min(clientX, window.innerWidth - menuWidth - 8));
  const top = Math.max(8, Math.min(clientY, window.innerHeight - menuHeight - 8));
  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function comparisonPathColor(edge) {
  const colors = ['#4a7fc1', '#a14f72'];
  return edge.sources.length > 1 ? '#7557a6' : colors[edge.sources[0] || 0];
}

function createComparisonPathElements(d, color, attributes = {}) {
  const pathAttributes = {
    d,
    fill: 'none',
    'stroke-linecap': 'round',
    'stroke-linejoin': 'round',
  };
  const halo = svgEl('path', {
    ...pathAttributes,
    class: 'comparison-path-halo',
    stroke: '#f5f4f0',
    'stroke-width': 5,
  });
  const path = svgEl('path', {
    ...pathAttributes,
    ...attributes,
    class: attributes.class || 'comparison-path',
    stroke: color,
    'stroke-width': 2,
  });
  return { halo, path };
}

function appendComparisonPath(svg, d, color, attributes = {}) {
  const elements = createComparisonPathElements(d, color, attributes);
  svg.appendChild(elements.halo);
  svg.appendChild(elements.path);
}

function drawComparisonPath(svg, anchor, child, edge) {
  const aligned = Math.abs(anchor.cx - child.cx) < 0.5;
  const turnY = Math.min(child.y - 18, anchor.clearY);
  const d = aligned
    ? `M ${anchor.cx} ${anchor.startY} L ${child.cx} ${child.y}`
    : `M ${anchor.cx} ${anchor.startY} L ${anchor.cx} ${turnY} ` +
      `L ${child.cx} ${turnY} L ${child.cx} ${child.y}`;

  appendComparisonPath(svg, d, comparisonPathColor(edge), {
    'data-child-id': edge.childId,
    'data-parent-id': edge.parentId,
    'data-routed': aligned ? 'straight' : 'orthogonal',
  });
}

function drawComparisonBranches(svg, anchor, branches) {
  if (!branches.length) return;
  if (branches.length === 1) {
    drawComparisonPath(svg, anchor, branches[0].child, branches[0].edge);
    return;
  }

  const branchY = Math.min(anchor.clearY, ...branches.map(branch => branch.child.y - 18));
  const sources = Array.from(new Set(branches.flatMap(branch => branch.edge.sources)));
  const trunkColor = comparisonPathColor({ sources });
  const routeElements = [createComparisonPathElements(
    `M ${anchor.cx} ${anchor.startY} L ${anchor.cx} ${branchY}`,
    trunkColor,
    { class: 'comparison-family-trunk' }
  )];

  branches.forEach(({ child, edge }) => {
    const aligned = Math.abs(anchor.cx - child.cx) < 0.5;
    const d = aligned
      ? `M ${anchor.cx} ${branchY} L ${child.cx} ${child.y}`
      : `M ${anchor.cx} ${branchY} L ${child.cx} ${branchY} L ${child.cx} ${child.y}`;
    routeElements.push(createComparisonPathElements(d, comparisonPathColor(edge), {
      'data-child-id': edge.childId,
      'data-parent-id': edge.parentId,
      'data-routed': aligned ? 'straight' : 'orthogonal',
    }));
  });
  routeElements.forEach(elements => svg.appendChild(elements.halo));
  routeElements.forEach(elements => svg.appendChild(elements.path));
}

function drawComparisonCouple(svg, firstParent, secondParent, couple) {
  const left = firstParent.cx < secondParent.cx ? firstParent : secondParent;
  const right = left === firstParent ? secondParent : firstParent;
  const y = Math.round((firstParent.y + secondParent.y) / 2 + NODE_H / 2);
  svg.appendChild(svgEl('line', {
    x1: left.cx + NODE_W / 2,
    y1: y,
    x2: right.cx - NODE_W / 2,
    y2: y,
    class: 'comparison-couple-path',
    stroke: '#999',
    'stroke-width': 1.5,
    'stroke-dasharray': '5,4',
    'data-couple-id': `${couple.firstParentId}:${couple.secondParentId}`,
  }));
  return {
    cx: (firstParent.cx + secondParent.cx) / 2,
    startY: y,
    clearY: Math.max(firstParent.y, secondParent.y) + NODE_H + 30,
  };
}

function renderCommonAncestorTree(firstId, secondId) {
  const firstPerson = buildPerson(firstId);
  const secondPerson = buildPerson(secondId);
  if (!firstPerson || !secondPerson) return;

  const graph = CommonAncestorLayout.buildMinimalGraph(firstId, secondId, PA);
  const couples = CommonAncestorLayout.findDisplayedCouples(graph, PA);
  const canvas = document.getElementById('canvas');
  const wrap = document.getElementById('canvas-wrap');
  canvas.innerHTML = '';
  currentComparison = [firstPerson.id, secondPerson.id];
  currentRootId = firstPerson.id;
  syncComparisonUrl(firstPerson.id, secondPerson.id);
  hidePersonContextMenu();
  document.getElementById('detail-panel').style.display = 'none';
  document.getElementById('descendant-limit-control').style.display = 'none';
  document.querySelectorAll('.mode-btn').forEach(button => {
    button.classList.remove('mode-btn-active');
  });

  const firstName = formatName(firstPerson.given, firstPerson.patronymic,
                               firstPerson.surname, firstPerson.maiden) || `Асоба #${firstPerson.id}`;
  const secondName = formatName(secondPerson.given, secondPerson.patronymic,
                                secondPerson.surname, secondPerson.maiden) || `Асоба #${secondPerson.id}`;
  const crumb = document.getElementById('crumb');
  crumb.textContent = `${firstName} ↔ ${secondName}`;
  crumb.title = crumb.textContent;
  const treeDocuments = document.getElementById('tree-documents');
  treeDocuments.style.display = 'none';
  treeDocuments.removeAttribute('href');

  if (!graph.commonAncestorIds.length) {
    const width = Math.max(320, wrap.clientWidth || window.innerWidth);
    const height = Math.max(240, wrap.clientHeight || window.innerHeight - 80);
    canvas.style.cssText = `width:${width}px;height:${height}px;position:relative`;
    const emptyState = document.createElement('div');
    emptyState.className = 'tree-empty-state';
    emptyState.textContent = 'Агульных продкаў не знойдзена';
    canvas.appendChild(emptyState);
    document.getElementById('tree-count').textContent = 'Асоб: 0';
    wrap.scrollLeft = 0;
    wrap.scrollTop = 0;
    return;
  }

  const maxRank = Math.max(...Object.values(graph.ranks));
  const comparisonGap = 64;
  const margin = 24;
  const sourceLayout = CommonAncestorLayout.layoutSourceTrees(graph, {
    nodeWidth: NODE_W,
    siblingGap: comparisonGap,
    sourceGap: comparisonGap,
  });
  const canvasW = sourceLayout.width + margin * 2;
  const canvasH = 24 + (maxRank + 1) * ROW_H + 40;
  canvas.style.cssText = `width:${canvasW}px;height:${canvasH}px;position:relative`;
  const svg = svgEl('svg', { class: 'connectors', style: `width:${canvasW}px;height:${canvasH}px` });
  canvas.appendChild(svg);

  const positions = new Map();
  graph.nodeIds.forEach(id => {
    positions.set(id, {
      cx: margin + sourceLayout.xById[id],
      y: 24 + (maxRank - graph.ranks[id]) * ROW_H,
    });
  });

  const nodeElements = new Map();
  graph.nodeIds.forEach(id => {
    const person = buildPerson(Number(id));
    const position = positions.get(id);
    if (!person || !position) return;
    const node = createNode(person, position.cx - NODE_W / 2, position.y, false);
    if (id === graph.selectedIds[0]) node.classList.add('is-comparison-first');
    if (id === graph.selectedIds[1]) node.classList.add('is-comparison-second');
    if (graph.commonAncestorIds.includes(id)) node.classList.add('is-common-ancestor');
    canvas.appendChild(node);
    nodeElements.set(id, node);
  });

  const coupledEdgeKeys = new Set();
  couples.forEach(couple => {
    couple.childIds.forEach(childId => {
      coupledEdgeKeys.add(`${childId}:${couple.firstParentId}`);
      coupledEdgeKeys.add(`${childId}:${couple.secondParentId}`);
    });
  });

  const singleParentEdges = graph.edges.filter(edge =>
    !coupledEdgeKeys.has(`${edge.childId}:${edge.parentId}`)
  );
  const edgesByParent = new Map();
  singleParentEdges.forEach(edge => {
    if (!edgesByParent.has(edge.parentId)) edgesByParent.set(edge.parentId, []);
    edgesByParent.get(edge.parentId).push(edge);
  });
  edgesByParent.forEach((parentEdges, parentId) => {
    const parent = positions.get(parentId);
    if (!parent) return;
    const parentNode = nodeElements.get(parentId);
    const parentBottom = parent.y + Math.max(NODE_H, parentNode ? parentNode.offsetHeight : 0);
    const branches = parentEdges
      .sort((a, b) => positions.get(a.childId).cx - positions.get(b.childId).cx)
      .map(edge => {
        const child = positions.get(edge.childId);
        return child ? { child, edge } : null;
      })
      .filter(Boolean);
    drawComparisonBranches(
      svg,
      { cx: parent.cx, startY: parentBottom, clearY: parentBottom + 18 },
      branches
    );
  });

  couples.forEach(couple => {
    const firstParent = positions.get(couple.firstParentId);
    const secondParent = positions.get(couple.secondParentId);
    if (!firstParent || !secondParent) return;
    const coupleAnchor = drawComparisonCouple(
      svg,
      firstParent,
      secondParent,
      couple
    );
    const branches = couple.childIds
      .sort((a, b) => positions.get(a).cx - positions.get(b).cx)
      .map(childId => {
        const child = positions.get(childId);
        if (!child) return null;
        const childEdges = graph.edges.filter(edge =>
          edge.childId === childId &&
          (edge.parentId === couple.firstParentId || edge.parentId === couple.secondParentId)
        );
        const sources = Array.from(new Set(childEdges.flatMap(edge => edge.sources)));
        return {
          child,
          edge: {
            childId,
            parentId: `${couple.firstParentId}:${couple.secondParentId}`,
            sources,
          },
        };
      })
      .filter(Boolean);
    drawComparisonBranches(svg, coupleAnchor, branches);
  });

  document.getElementById('tree-count').textContent = `Асоб: ${nodeElements.size}`;
  const vw = wrap.clientWidth || window.innerWidth;
  const vh = wrap.clientHeight || window.innerHeight - 80;
  const padLeft = Math.max(0, Math.round((vw - canvasW) / 2));
  const padTop = Math.max(0, Math.round((vh - canvasH) / 2));
  canvas.style.cssText += `;margin-left:${padLeft}px;margin-top:${padTop}px`;
  wrap.scrollLeft = Math.max(0, (canvasW + padLeft - vw) / 2);
  const selectedY = 24 + maxRank * ROW_H;
  wrap.scrollTop = Math.max(0, selectedY + padTop - Math.round(vh * 2 / 3));
}

function navigate(id) {
  currentComparison = null;
  hidePersonContextMenu();
  document.getElementById('detail-panel').style.display = 'none';
  renderTree(buildTree(id));
}

function updateDescendantLimitControl(rootId) {
  const control = document.getElementById('descendant-limit-control');
  const options = document.getElementById('descendant-limit-options');
  if (!control || !options) return;

  control.style.display = currentMode === 'descendants' ? 'flex' : 'none';

  const maxDepth = computeDescendantDepth(rootId);
  const nextValue = descendantGenerationLimit == null || maxDepth <= 0 || descendantGenerationLimit >= maxDepth
    ? 'all'
    : String(descendantGenerationLimit);

  options.innerHTML = '';

  function addLimitButton(value, label) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = [
      'generation-limit-btn',
      value === nextValue ? 'generation-limit-btn-active' : '',
    ].filter(Boolean).join(' ');
    button.dataset.limit = value;
    button.textContent = label;
    button.setAttribute('aria-pressed', value === nextValue ? 'true' : 'false');
    button.addEventListener('click', () => {
      descendantGenerationLimit = value === 'all' ? null : Number(value);
      if (currentRootId) renderTree(buildTree(currentRootId));
    });
    options.appendChild(button);
  }

  addLimitButton('all', 'Усе');

  for (let generation = 1; generation < maxDepth; generation += 1) {
    addLimitButton(String(generation), String(generation));
  }

  descendantGenerationLimit = nextValue === 'all' ? null : Number(nextValue);
}

function setMode(mode) {
  if (!TREE_MODES.has(mode)) return;
  currentComparison = null;
  currentMode = mode;
  syncModeButtons();
  if (currentRootId) updateDescendantLimitControl(currentRootId);
  if (currentRootId) renderTree(buildTree(currentRootId));
}

function initUI() {
  // Mode buttons
  document.querySelectorAll('.mode-btn').forEach(btn => {
    btn.addEventListener('click', () => setMode(btn.dataset.mode));
  });
  syncModeButtons();

  document.getElementById('detail-close').addEventListener('click', () => {
    document.getElementById('detail-panel').style.display = 'none';
    document.querySelectorAll('.node.is-selected').forEach(n => n.classList.remove('is-selected'));
  });

  const contextMenu = document.getElementById('person-context-menu');
  document.getElementById('context-show-tree').addEventListener('click', () => {
    const personId = Number(contextMenu.dataset.personId);
    if (!personId) return;
    navigate(personId);
  });
  document.getElementById('context-compare').addEventListener('click', () => {
    const personId = Number(contextMenu.dataset.personId);
    const person = buildPerson(personId);
    if (!person) return;

    if (!contextComparisonPerson) {
      contextComparisonPerson = person;
      updateContextComparisonUi();
      hidePersonContextMenu();
      return;
    }
    if (contextComparisonPerson.id === person.id) {
      clearContextComparisonPerson();
      hidePersonContextMenu();
      return;
    }

    const firstPerson = contextComparisonPerson;
    clearContextComparisonPerson();
    hidePersonContextMenu();
    renderCommonAncestorTree(firstPerson.id, person.id);
  });
  document.getElementById('comparison-pick-clear').addEventListener('click', () => {
    clearContextComparisonPerson();
    hidePersonContextMenu();
  });
  updateContextComparisonUi();

  document.addEventListener('click', event => {
    if (!contextMenu.contains(event.target)) hidePersonContextMenu();
  });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') hidePersonContextMenu();
  });
  document.getElementById('canvas-wrap').addEventListener('scroll', hidePersonContextMenu);
  window.addEventListener('resize', hidePersonContextMenu);
  window.addEventListener('blur', hidePersonContextMenu);

  window.addEventListener('hashchange', () => {
    const hashValue = location.hash.slice(1);
    if (!hashValue) return;
    const id = resolvePersonId(hashValue);
    if (id && id !== currentRootId) navigate(id);
  });
}

// ── Search ───────────────────────────────────────────────────

function findPersonMatches(rawQuery) {
  const normalize = value => String(value || '')
    .toLowerCase()
    .replace(/[()[\]{},/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const query = normalize(rawQuery);
  const words = query.split(' ').filter(Boolean);
  if (!words.length) return [];

  const isOrderedPrefixMatch = (queryWords, orderedFields) => {
    let fieldIndex = 0;
    return queryWords.every(word => {
      while (fieldIndex < orderedFields.length && !orderedFields[fieldIndex].startsWith(word)) {
        fieldIndex += 1;
      }
      if (fieldIndex >= orderedFields.length) return false;
      fieldIndex += 1;
      return true;
    });
  };

  const matches = [];
  for (const r of SI) {
    const [, , given, patronymic, surname, maiden, birthYear] = r;
    const fields = [given, patronymic, surname, maiden]
      .filter(Boolean)
      .map(normalize);
    const allMatch = words.every(word =>
      fields.some(field => field.startsWith(word) || field.includes(word))
    );
    if (!allMatch) continue;

    const orderedVariants = [
      [surname, given, patronymic].filter(Boolean).map(normalize),
    ];
    if (maiden && maiden !== surname) {
      orderedVariants.push([maiden, given, patronymic].filter(Boolean).map(normalize));
    }
    const displayName = normalize(formatName(given, patronymic, surname, maiden));
    const nameVariants = [displayName, ...orderedVariants.map(variant => variant.join(' '))];
    const allPrefix = words.every(word => fields.some(field => field.startsWith(word)));
    let relevance = 5;
    if (nameVariants.some(name => name === query)) relevance = 0;
    else if (nameVariants.some(name => name.startsWith(query))) relevance = 1;
    else if (nameVariants.some(name => name.includes(query))) relevance = 2;
    else if (orderedVariants.some(variant => isOrderedPrefixMatch(words, variant))) relevance = 3;
    else if (allPrefix) relevance = 4;

    matches.push({
      r,
      relevance,
      name: displayName,
      birthYear: birthYear || Number.MAX_SAFE_INTEGER,
    });
  }

  matches.sort((a, b) => {
    if (a.relevance !== b.relevance) return a.relevance - b.relevance;
    const alphabetical = a.name.localeCompare(b.name, 'ru', { sensitivity: 'base' });
    if (alphabetical) return alphabetical;
    return a.birthYear - b.birthYear || a.r[0] - b.r[0];
  });
  return matches;
}

function appendPersonSearchResult(container, row, onSelect) {
  const [id, sex, given, patronymic, surname, maiden, birthYear] = row;
  const name = formatName(given, patronymic, surname, maiden) || `Асоба #${id}`;
  const idLabel = NU[id] != null ? `#${NU[id]}` : `~${id}`;
  const details = [birthYear ? `н. ${birthYear}` : '', sex === 1 ? 'муж.' : 'жан.', idLabel]
    .filter(Boolean)
    .join(' · ');
  const result = document.createElement('div');
  result.className = 'search-result';
  result.innerHTML = `
    <div class="search-result-name">${name}</div>
    <div class="search-result-sub">${details}</div>
  `.trim();
  result.addEventListener('click', () => onSelect(id));
  container.appendChild(result);
}

function initSearch() {
  const input   = document.getElementById('search-input');
  const results = document.getElementById('search-results');
  const pageSize = 20;
  let debounce  = null;
  let matches = [];
  let renderedCount = 0;

  function appendMatches() {
    const nextMatches = matches.slice(renderedCount, renderedCount + pageSize);

    nextMatches.forEach(({ r }) => {
      appendPersonSearchResult(results, r, id => {
        results.style.display = 'none';
        input.value = '';
        navigate(id);
      });
    });

    renderedCount += nextMatches.length;
  }

  input.addEventListener('input', () => {
    clearTimeout(debounce);
    const raw = input.value.trim().toLowerCase();
    if (raw.length < 2) { results.style.display = 'none'; return; }

    debounce = setTimeout(() => {
      matches = findPersonMatches(raw);

      results.innerHTML = '';
      if (!matches.length) { results.style.display = 'none'; return; }
      renderedCount = 0;
      results.scrollTop = 0;
      appendMatches();
      results.style.display = 'block';
    }, 250);
  });

  results.addEventListener('scroll', () => {
    const nearBottom = results.scrollTop + results.clientHeight >= results.scrollHeight - 40;
    if (nearBottom && renderedCount < matches.length) appendMatches();
  });

  document.addEventListener('click', e => {
    if (!input.contains(e.target) && !results.contains(e.target)) {
      results.style.display = 'none';
    }
  });
}
